import React, { useState, useRef, useEffect } from "react";

const apiBase = "http://localhost:8000";

function App() {
  const [question, setQuestion] = useState("");
  const [output, setOutput] = useState("");
  const [loading, setLoading] = useState(false);
  const [operationProgress, setOperationProgress] = useState(null);
  const [dataInfo, setDataInfo] = useState(null);
  const [lastIntent, setLastIntent] = useState(null);
  
  // Enhanced Excel data reading with intelligent sampling
  async function getExcelData(sampleOnly = false) {
    return Excel.run(async (context) => {
      const range = context.workbook.getSelectedRange();
      range.load("values, address, rowCount, columnCount");
      await context.sync();
      
      const fullData = range.values;
      const dataSize = {
        rows: range.rowCount,
        columns: range.columnCount,
        address: range.address
      };
      
      // For large datasets, implement client-side sampling if needed
      let processedData = fullData;
      
      if (dataSize.rows > 50000 && sampleOnly) {
        // Client-side sampling for very large selections
        processedData = intelligentSample(fullData, 10000);
      }
      
      return {
        values: processedData,
        address: range.address,
        metadata: {
          originalRows: dataSize.rows,
          originalColumns: dataSize.columns,
          sampledRows: processedData.length,
          isSampled: processedData.length !== dataSize.rows
        }
      };
    });
  }
  
  function intelligentSample(data, maxSample) {
    if (data.length <= maxSample) return data;
    
    const sample = [];
    const step = Math.floor(data.length / maxSample);
    
    // Include header if available
    if (data.length > 0) sample.push(data[0]);
    
    // Systematic sampling
    for (let i = step; i < data.length && sample.length < maxSample; i += step) {
      sample.push(data[i]);
    }
    
    return sample;
  }
  
  // Enhanced intent classification
  const classifyIntent = async () => {
    setLoading(true);
    setOutput("Analyzing your request...");
    
    try {
      const { values, address, metadata } = await getExcelData(true);
      setDataInfo(metadata);
      
      const resp = await fetch(`${apiBase}/classify_intent`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ 
          table: values, 
          address, 
          question,
          metadata 
        })
      });
      
      const intent = await resp.json();
      setLastIntent(intent);
      
      setOutput(`
        Analysis Classification:
        • Action Type: ${intent.action_type.toUpperCase()}
        • Confidence: ${(intent.confidence * 100).toFixed(1)}%
        • Reasoning: ${intent.reasoning}
        ${intent.suggested_operations ? `• Suggested Operations: ${intent.suggested_operations.join(', ')}` : ''}
        
        Dataset Info: ${metadata.originalRows.toLocaleString()} rows, ${metadata.originalColumns} columns
        ${metadata.isSampled ? `(Analyzed sample of ${metadata.sampledRows.toLocaleString()} rows)` : ''}
      `);
      
    } catch (error) {
      setOutput(`Classification error: ${error.message}`);
    } finally {
      setLoading(false);
    }
  };
  
  // Enhanced AI analysis with intelligent data handling
  const askAI = async () => {
    setLoading(true);
    setOutput("Analyzing your data...");
    setOperationProgress({ stage: "reading_data", progress: 20 });
    
    try {
      const { values, address, metadata } = await getExcelData();
      setDataInfo(metadata);
      
      setOperationProgress({ stage: "analyzing", progress: 50 });
      
      const resp = await fetch(`${apiBase}/analyze`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ 
          table: values, 
          address, 
          question,
          metadata 
        })
      });
      
      const { answer } = await resp.json();
      
      setOperationProgress({ stage: "complete", progress: 100 });
      setOutput(answer);
      
    } catch (error) {
      setOutput(`Analysis error: ${error.message}`);
    } finally {
      setLoading(false);
      setTimeout(() => setOperationProgress(null), 2000);
    }
  };
  
  // Enhanced Excel actions with progress tracking
  const executeExcelAction = async () => {
    setLoading(true);
    setOutput("Preparing Excel operations...");
    setOperationProgress({ stage: "initializing", progress: 10 });
    
    try {
      const { values, address, metadata } = await getExcelData();
      setDataInfo(metadata);
      
      setOperationProgress({ stage: "processing", progress: 30 });
      setOutput("Processing your request with AI...");
      
      const resp = await fetch(`${apiBase}/action`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ 
          table: values, 
          address, 
          question,
          metadata 
        })
      });
      
      const actionResult = await resp.json();
      
      if (!actionResult.success) {
        setOutput(`Action failed: ${actionResult.errors.join(", ")}`);
        return;
      }
      
      setOperationProgress({ stage: "creating_worksheets", progress: 60 });
      setOutput("Creating worksheets and formulas...");
      
      // Execute Excel operations
      await executeExcelOperations(actionResult);
      
      setOperationProgress({ stage: "complete", progress: 100 });
      setOutput(`
        Excel operations completed successfully!
        
        Operations performed: ${actionResult.metadata?.operations_performed?.join(", ") || "Analysis"}
        Worksheets created: ${actionResult.worksheets?.length || 0}
        Formulas generated: ${actionResult.formulas?.length || 0}
        
        Check the new worksheets for your analysis results.
      `);
      
    } catch (error) {
      setOutput(`Excel action error: ${error.message}`);
    } finally {
      setLoading(false);
      setTimeout(() => setOperationProgress(null), 3000);
    }
  };
  
  // Execute complex Excel operations
  async function executeExcelOperations(actionResult) {
    await Excel.run(async (context) => {
      const workbook = context.workbook;
      
      // Create worksheets
      for (const sheetConfig of actionResult.worksheets || []) {
        const worksheet = workbook.worksheets.add(sheetConfig.name);
        
        // Set up layout
        if (sheetConfig.layout) {
          for (const [key, layoutItem] of Object.entries(sheetConfig.layout)) {
            if (layoutItem.cell && layoutItem.value) {
              const cell = worksheet.getRange(layoutItem.cell);
              cell.values = [[layoutItem.value]];
              
              // Apply basic styling
              if (layoutItem.style === "title") {
                cell.format.font.size = 16;
                cell.format.font.bold = true;
              } else if (layoutItem.style === "header") {
                cell.format.font.bold = true;
                cell.format.fill.color = "#D3D3D3";
              }
            }
          }
        }
        
        // Add formulas
        for (const formulaItem of sheetConfig.formulas || []) {
          try {
            const formulaCell = worksheet.getRange(formulaItem.cell);
            formulaCell.formulas = [[formulaItem.formula]];
            
            // Add error handling - highlight cells with formula errors in red
            if (formulaItem.error_handling) {
              const errorRule = worksheet.conditionalFormats.add(Excel.ConditionalFormatType.custom);
              errorRule.customFormat.condition = `ISERROR(${formulaItem.cell})`;
              errorRule.customFormat.format.fill.color = "#FFB6C1";
            }
            
          } catch (formulaError) {
            // If formula fails, put it as text with red background
            const errorCell = worksheet.getRange(formulaItem.cell);
            errorCell.values = [[formulaItem.formula]];
            errorCell.format.fill.color = "#FFB6C1";
            
            // Add comment with error details
            errorCell.comment.text = `Formula error: ${formulaError.message}`;
          }
        }
        
        // Apply conditional formatting
        for (const condFormat of sheetConfig.conditional_formatting || []) {
          try {
            const range = worksheet.getRange(condFormat.range);
            const conditionalFormat = range.conditionalFormats.add(Excel.ConditionalFormatType[condFormat.rule] || Excel.ConditionalFormatType.colorScale);
            
            if (condFormat.style === "green_gradient") {
              conditionalFormat.colorScale.criteria = {
                minimum: { formula: null, type: Excel.ConditionalFormatColorCriterionType.lowestValue },
                maximum: { formula: null, type: Excel.ConditionalFormatColorCriterionType.highestValue }
              };
            }
          } catch (formatError) {
            console.warn("Conditional formatting failed:", formatError);
          }
        }
      }
      
      // Add standalone formulas
      const activeSheet = workbook.worksheets.getActiveWorksheet();
      for (const formulaItem of actionResult.formulas || []) {
        try {
          const formulaCell = activeSheet.getRange(formulaItem.cell);
          formulaCell.formulas = [[formulaItem.formula]];
        } catch (formulaError) {
          console.warn("Formula creation failed:", formulaError);
        }
      }
      
      await context.sync();
    });
  }
  
  // Data quality audit
  const auditData = async () => {
    setLoading(true);
    setOutput("Auditing data quality...");
    
    try {
      const { values, address, metadata } = await getExcelData();
      
      const resp = await fetch(`${apiBase}/ai_audit`, {
        method: "POST", 
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ table: values, address })
      });
      
      const { audit } = await resp.json();
      setOutput(audit);
      
    } catch (error) {
      setOutput(`Audit error: ${error.message}`);
    } finally {
      setLoading(false);
    }
  };
  
  // Progress indicator component
  const ProgressIndicator = () => {
    if (!operationProgress) return null;
    
    const stages = {
      initializing: "Initializing...",
      reading_data: "Reading Excel data...",
      analyzing: "Analyzing with AI...",
      processing: "Processing request...",
      creating_worksheets: "Creating worksheets...",
      complete: "Complete!"
    };
    
    return (
      <div style={{ marginTop: 10, padding: 10, background: "#f0f8ff", borderRadius: 5 }}>
        <div style={{ fontSize: 12, marginBottom: 5 }}>
          {stages[operationProgress.stage] || operationProgress.stage}
        </div>
        <div style={{ width: "100%", height: 8, background: "#e0e0e0", borderRadius: 4 }}>
          <div 
            style={{
              width: `${operationProgress.progress}%`,
              height: "100%",
              background: "#4CAF50",
              borderRadius: 4,
              transition: "width 0.3s ease"
            }}
          />
        </div>
        <div style={{ fontSize: 10, color: "#666", marginTop: 2 }}>
          {operationProgress.progress}% complete
        </div>
      </div>
    );
  };
  
  return (
    <div style={{ padding: 20, fontFamily: "Segoe UI, Tahoma, Geneva, Verdana, sans-serif" }}>
      <h2 style={{ color: "#0078d4", marginBottom: 10 }}>AI Excel Assistant (Enhanced)</h2>
      <p style={{ color: "#666", marginBottom: 15 }}>
        Select data in Excel, ask your question, and let AI decide the best approach.
      </p>
      
      {/* Data info display */}
      {dataInfo && (
        <div style={{ 
          background: "#f9f9f9", 
          padding: 10, 
          borderRadius: 5, 
          fontSize: 12, 
          marginBottom: 10,
          color: "#555"
        }}>
          📊 Dataset: {dataInfo.originalRows?.toLocaleString()} rows × {dataInfo.originalColumns} columns
          {dataInfo.isSampled && (
            <span style={{ color: "#ff6b00" }}>
              {" "}(Sampled: {dataInfo.sampledRows?.toLocaleString()} rows analyzed)
            </span>
          )}
        </div>
      )}
      
      {/* Question input */}
      <textarea
        style={{ 
          width: "98%", 
          minHeight: 60,
          marginBottom: 15,
          padding: 10,
          border: "1px solid #ccc",
          borderRadius: 4,
          fontSize: 14,
          resize: "vertical"
        }}
        value={question}
        onChange={(e) => setQuestion(e.target.value)}
        placeholder="e.g. What are the top 10 SKUs by sales? Create a performance dashboard. Generate formulas for ranking analysis."
      />
      
      {/* Action buttons */}
      <div style={{ marginBottom: 15 }}>
        <button 
          onClick={classifyIntent} 
          disabled={loading || !question.trim()}
          style={{
            padding: "8px 16px",
            marginRight: 10,
            background: "#0078d4",
            color: "white",
            border: "none",
            borderRadius: 4,
            cursor: loading ? "not-allowed" : "pointer",
            opacity: loading || !question.trim() ? 0.6 : 1
          }}
        >
          🤔 Classify Intent
        </button>
        
        <button 
          onClick={askAI} 
          disabled={loading || !question.trim()}
          style={{
            padding: "8px 16px",
            marginRight: 10,
            background: "#107C10",
            color: "white", 
            border: "none",
            borderRadius: 4,
            cursor: loading ? "not-allowed" : "pointer",
            opacity: loading || !question.trim() ? 0.6 : 1
          }}
        >
          💬 Ask AI
        </button>
        
        <button 
          onClick={executeExcelAction} 
          disabled={loading || !question.trim()}
          style={{
            padding: "8px 16px",
            marginRight: 10,
            background: "#D13438",
            color: "white",
            border: "none", 
            borderRadius: 4,
            cursor: loading ? "not-allowed" : "pointer",
            opacity: loading || !question.trim() ? 0.6 : 1
          }}
        >
          ⚡ Excel Action
        </button>
        
        <button 
          onClick={auditData} 
          disabled={loading}
          style={{
            padding: "8px 16px",
            background: "#8A2BE2",
            color: "white",
            border: "none",
            borderRadius: 4,
            cursor: loading ? "not-allowed" : "pointer",
            opacity: loading ? 0.6 : 1
          }}
        >
          🔍 Audit Data
        </button>
      </div>
      
      {/* Progress indicator */}
      <ProgressIndicator />
      
      {/* Output display */}
      <div style={{ 
        marginTop: 20, 
        minHeight: 100,
        padding: 15,
        background: "#f8f9fa",
        borderRadius: 5,
        whiteSpace: "pre-wrap",
        fontSize: 13,
        lineHeight: 1.4,
        border: "1px solid #e9ecef"
      }}>
        {output || "Results will appear here..."}
      </div>
      
      {/* Loading indicator */}
      {loading && (
        <div style={{ 
          marginTop: 10,
          padding: 10,
          background: "#fff3cd",
          border: "1px solid #ffeaa7",
          borderRadius: 4,
          fontSize: 12,
          color: "#856404"
        }}>
          🔄 Processing your request... This may take a moment for large datasets.
        </div>
      )}
      
      {/* Intent display */}
      {lastIntent && !loading && (
        <div style={{
          marginTop: 15,
          padding: 10,
          background: lastIntent.action_type === "excel" ? "#e8f5e8" : "#e8f4fd",
          borderRadius: 4,
          fontSize: 11
        }}>
          <strong>Last Classification:</strong> {lastIntent.action_type.toUpperCase()} 
          ({(lastIntent.confidence * 100).toFixed(0)}% confidence)
          {lastIntent.suggested_operations && (
            <div style={{ marginTop: 5 }}>
              <strong>Operations:</strong> {lastIntent.suggested_operations.join(", ")}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default App;
